def concatenate_elements(test_tup):
    """Write a function to perform the adjacent element concatenation in the given tuples.

    Concatenate each element with the following element, so a tuple of
    length ``n`` produces a tuple of length ``n - 1`` (an empty or
    single-element tuple therefore produces an empty tuple). String,
    bytes, list and tuple elements are concatenated with ``+``; other
    values (for example numbers) are first converted to strings, as
    concatenation is a textual operation for them.
    """
    return tuple(
        first + second
        if type(first) is type(second)
        and isinstance(first, (str, bytes, list, tuple))
        else str(first) + str(second)
        for first, second in zip(test_tup, test_tup[1:])
    )
